#!/bin/bash
# Everything generated by this workflow stays in one removable repository-local root.
set -euo pipefail
personal_repo="$(cd "$(dirname "$0")/.." && pwd)"
personal_root="$personal_repo/.tools/macos14-personal"
personal_triplet=x64-osx-snow-shot-macos14-static
personal_jobs="${SNOW_PERSONAL_JOBS:-2}"
[[ "$personal_jobs" =~ ^[1-9][0-9]*$ ]] || { echo 'SNOW_PERSONAL_JOBS must be positive' >&2; exit 2; }
personal_mode="${1:-status}"
[[ $# == 0 ]] || shift
personal_version="$(python3 - "$personal_repo/snow_shot/packaging/macos/maintained-release.json" <<'PY'
import json, re, sys
with open(sys.argv[1]) as source:
    release = json.load(source)
numeric_version = r'(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
if any(not isinstance(release.get(key), str) or not re.fullmatch(numeric_version, release[key])
       for key in ('version', 'upstreamVersion')):
    raise SystemExit('Release versions must contain three numeric components')
if type(release.get('buildNumber')) is not int or release['buildNumber'] < 1:
    raise SystemExit('Release buildNumber must be a positive integer')
print(f"{release['version']}+up.{release['upstreamVersion']}")
PY
)"
personal_release="$personal_root/artifacts/$personal_version"
personal_dmg_name="snow-shot-$personal_version-intel.dmg"

if [[ "$personal_mode" == clean ]]; then
    # A missing marker, symlink, or unexpected parent must never widen deletion.
    python3 - "$personal_root" "$@" <<'PY'
from pathlib import Path
import shutil
import sys
root = Path(sys.argv[1])
if sys.argv[2:] not in ([], ['--all']):
    raise SystemExit('Usage: macos14-personal.sh clean [--all]')
if not root.exists():
    raise SystemExit(0)
marker = root / '.personal-build-root'
if root.is_symlink() or root.parent.is_symlink() or marker.is_symlink() or not marker.is_file():
    raise SystemExit(f'Refusing to remove an unmarked or linked directory: {root}')
if sys.argv[2:] == ['--all']:
    print(f'Removing tools, downloads, builds, artifacts and personal test data: {root}')
    shutil.rmtree(root)
else:
    for name in ('build', 'performance', 'qt-build', 'rust-tests', 'native-tests', 'deployment-guard-tests', 'tmp'):
        path = root / name
        if path.is_symlink():
            raise SystemExit(f'Refusing linked build directory: {path}')
        if path.exists():
            print(f'Removing {path}')
            shutil.rmtree(path)
    print('Kept tools, downloads, logs, artifacts and user-data. Use clean --all to remove them too.')
PY
    exit
fi

[[ $# == 0 || "$personal_mode" == run || "$personal_mode" == test || "$personal_mode" == measure || "$personal_mode" == build-target ]] || {
    echo 'Unexpected arguments' >&2; exit 2;
}
[[ "$(uname -s)" == Darwin && "$(uname -m)" == x86_64 ]] || {
    echo 'This personal workflow requires an Intel Mac' >&2; exit 2;
}
mkdir -p "$personal_root"/{downloads,logs,tmp,host,cargo,rustup,cache,artifacts,user-data}
touch "$personal_root/.personal-build-root"
export TMPDIR="$personal_root/tmp"
export CARGO_HOME="$personal_root/cargo"
export RUSTUP_HOME="$personal_root/rustup"
export RUSTUP_TOOLCHAIN=1.97.1
export CARGO_TARGET_DIR="$personal_root/rust-tests"
export CARGO_BUILD_JOBS="$personal_jobs"
export MACOSX_DEPLOYMENT_TARGET=14.4
export VCPKG_ROOT="$personal_root/vcpkg"
export VCPKG_DISABLE_METRICS=1
export VCPKG_MAX_CONCURRENCY="$personal_jobs"
export VCPKG_DEFAULT_BINARY_CACHE="$personal_root/cache/vcpkg"
export XDG_CACHE_HOME="$personal_root/cache"
export PIP_CACHE_DIR="$personal_root/cache/pip"
export CLANG_MODULE_CACHE_PATH="$personal_root/cache/clang-modules"
export PYTHONPYCACHEPREFIX="$personal_root/cache/pycache"
export LIBCLANG_PATH="$(xcode-select -p)/Toolchains/XcodeDefault.xctoolchain/usr/lib"
export SNOW_SHOT_PERSONAL_DATA_DIR="$personal_root/user-data"
export PATH="$personal_root/host/venv/bin:$personal_root/host/bin:$personal_root/rustup/toolchains/1.97.1-x86_64-apple-darwin/bin:$PATH"
mkdir -p "$VCPKG_DEFAULT_BINARY_CACHE"

personal_python_certificates() {
    # Use the private Python environment's CA bundle, leaving system trust unchanged.
    if [[ -z "${SSL_CERT_FILE:-}" && -x "$personal_root/host/venv/bin/python" ]]; then
        export SSL_CERT_FILE="$("$personal_root/host/venv/bin/python" -c \
            'import pip._vendor.certifi; print(pip._vendor.certifi.where())')"
    fi
}
personal_python_certificates

personal_fetch() {
    local url="$1" output="$2"
    [[ -f "$output" ]] && return
    curl --http1.1 --fail --location --proto '=https' --proto-redir '=https' --retry 2 \
        --output "$output.part" "$url"
    mv "$output.part" "$output"
}

personal_bootstrap() {
    if [[ ! -x "$personal_root/host/venv/bin/cmake" ]]; then
        python3 -m venv "$personal_root/host/venv"
        "$personal_root/host/venv/bin/python" -m pip --cache-dir "$personal_root/cache/pip" \
            install cmake==4.4.4 ninja==1.13.2
    fi
    personal_python_certificates
    if [[ ! -x "$personal_root/rustup/toolchains/1.97.1-x86_64-apple-darwin/bin/rustc" ]]; then
        command -v rustup >/dev/null
        rustup toolchain install 1.97.1 --profile minimal --component rustfmt \
            --component clippy --target x86_64-apple-darwin
    fi
    if [[ ! -x "$personal_root/host/bin/pkgconf" ]]; then
        personal_fetch https://distfiles.ariadne.space/pkgconf/pkgconf-2.5.1.tar.xz \
            "$personal_root/downloads/pkgconf-2.5.1.tar.xz"
        tar -xf "$personal_root/downloads/pkgconf-2.5.1.tar.xz" -C "$personal_root/host"
        (cd "$personal_root/host/pkgconf-2.5.1"
            ./configure --prefix="$personal_root/host" --with-pkg-config-dir= --disable-shared
            make -j"$personal_jobs"
            make install)
    fi
    [[ -e "$personal_root/host/bin/pkg-config" ]] || \
        ln -s pkgconf "$personal_root/host/bin/pkg-config"
    if [[ ! -x "$personal_root/host/bin/nasm" ]]; then
        personal_fetch https://www.nasm.us/pub/nasm/releasebuilds/2.16.03/nasm-2.16.03.tar.xz \
            "$personal_root/downloads/nasm-2.16.03.tar.xz"
        tar -xf "$personal_root/downloads/nasm-2.16.03.tar.xz" -C "$personal_root/host"
        (cd "$personal_root/host/nasm-2.16.03"
            ./configure --prefix="$personal_root/host"
            make -j"$personal_jobs"
            make install)
    fi
    if [[ ! -x "$VCPKG_ROOT/vcpkg" ]]; then
        if [[ ! -d "$VCPKG_ROOT/.git" ]]; then
            git clone --filter=blob:none --no-checkout https://github.com/microsoft/vcpkg.git "$VCPKG_ROOT"
        fi
        git -C "$VCPKG_ROOT" fetch origin 4497409a47f19db373a410a0efb84eca4747adbf --depth=1
        git -C "$VCPKG_ROOT" checkout --detach 4497409a47f19db373a410a0efb84eca4747adbf
        "$VCPKG_ROOT/bootstrap-vcpkg.sh" -disableMetrics
    fi
}

personal_dependencies() {
    "$VCPKG_ROOT/vcpkg" install --x-manifest-root="$personal_repo" \
        --x-install-root="$personal_root/installed" --triplet="$personal_triplet" \
        --host-triplet="$personal_triplet" --x-feature=snow-shot --x-feature=macos14-personal-jpeg \
        --overlay-ports="$personal_repo/cmake/vcpkg-overlay-ports" \
        --overlay-triplets="$personal_repo/cmake/vcpkg-overlay-triplets" --clean-after-build
}

personal_qt_dependencies() {
    mkdir -p "$personal_root/qt-manifest"
    python3 - "$personal_repo" "$personal_root/qt-manifest" <<'PY'
from pathlib import Path
import json
import sys
repo, output = map(Path, sys.argv[1:])
(output / 'vcpkg.json').write_text(json.dumps({
    'name': 'snow-personal-qt-dependencies', 'version-semver': '0.1.0',
    'dependencies': ['zlib', {'name': 'libpng', 'features': ['apng']}],
}, indent=2) + '\n')
(output / 'vcpkg-configuration.json').write_bytes((repo / 'vcpkg-configuration.json').read_bytes())
PY
    "$VCPKG_ROOT/vcpkg" install --x-manifest-root="$personal_root/qt-manifest" \
        --x-install-root="$personal_root/qt-deps" --triplet="$personal_triplet" \
        --host-triplet="$personal_triplet" --overlay-ports="$personal_repo/cmake/vcpkg-overlay-ports" \
        --overlay-triplets="$personal_repo/cmake/vcpkg-overlay-triplets" --clean-after-build
}

personal_qt() {
    local version qt_builder
    version="$(python3 "$personal_repo/scripts/validate-static-qt.py" --print-version)"
    personal_fetch "https://download.qt.io/official_releases/qt/${version%.*}/$version/single/qt-everywhere-src-$version.tar.xz" \
        "$personal_root/downloads/qt-everywhere-src-$version.tar.xz"
    # Load the long-running builder before execution so source edits cannot shift
    # Bash's input offset while configure/build subprocesses are running.
    qt_builder="$(cat "$personal_repo/scripts/build-static-qt.sh")"
    bash -c "$qt_builder" "$personal_repo/scripts/build-static-qt.sh" \
        --arch x64 --parallel "$personal_jobs" --with-testlib \
        --install-prefix "$personal_root/qt" --dependency-prefix "$personal_root/qt-deps/$personal_triplet" \
        --source-dir "$personal_root/downloads/qt-everywhere-src-$version" --build-dir "$personal_root/qt-build"
}

personal_configure() {
    local directory="$1" tests="$2" benchmarks="$3"
    local preset=snow-shot-macos14-x64-release
    [[ "$benchmarks" != ON ]] || preset=snow-shot-macos14-x64-performance
    (cd "$personal_repo"
    cmake --preset "$preset" -S "$personal_repo" -B "$directory" -G Ninja \
        -DCMAKE_TOOLCHAIN_FILE="$VCPKG_ROOT/scripts/buildsystems/vcpkg.cmake" \
        -DCMAKE_BUILD_TYPE=Release -DCMAKE_OSX_ARCHITECTURES=x86_64 -DCMAKE_OSX_DEPLOYMENT_TARGET=14.4 \
        -DVCPKG_TARGET_TRIPLET="$personal_triplet" -DVCPKG_HOST_TRIPLET="$personal_triplet" \
        -DVCPKG_INSTALLED_DIR="$personal_root/installed" '-DVCPKG_MANIFEST_FEATURES=snow-shot;macos14-personal-jpeg' \
        -DVCPKG_OVERLAY_PORTS="$personal_repo/cmake/vcpkg-overlay-ports" \
        -DVCPKG_OVERLAY_TRIPLETS="$personal_repo/cmake/vcpkg-overlay-triplets" \
        -DQt6_DIR="$personal_root/qt/lib/cmake/Qt6" -DSNOW_QT_STATIC_DIR="$personal_root/qt/lib/cmake/Qt6" \
        -DSNOW_APPS_MACOS14_PERSONAL=ON -DSNOW_APPS_BUILD_SNOW_SHOT_MINI=OFF \
        -DSNOW_MACOS_LTO_CACHE="$personal_root/cache/thinlto" \
        -DSNOW_APPS_BUILD_IMAGE_VIEWER=OFF -DSNOW_APPS_BUILD_DRAW_ENGINE_DEMO=OFF \
        -DSNOW_APPS_BUILD_TESTS="$tests" -DSNOW_SHOT_BUILD_TESTS="$tests" \
        -DSNOW_APPS_BUILD_BENCHMARKS="$benchmarks" -DSNOW_APPS_RELEASE_STATIC=ON \
        -DSNOW_APPS_QT_STATIC=ON -DSNOW_APPS_PACKAGE_SNOW_SHOT=OFF \
        -DSNOW_MACOS_CODESIGN_IDENTITY=- -DSNOW_SHOT_ENABLE_MCP=OFF \
        -DSNOW_APPS_ENABLE_RELEASE_OPTIMIZATION=ON -DSNOW_APPS_ENABLE_RELEASE_SIZE_OPTIMIZATION=ON \
        -DSNOW_RUST_TARGET=x86_64-apple-darwin -DSNOW_RUST_CARGO_TARGET_DIR="$directory/cargo" \
        -DSNOW_MACOS_OCR_CACHE="$personal_root/cache/ocr" -DSNOW_IMAGE_PROFILE=redistributable \
        -DSNOW_SHOT_QR_MODELS_CACHE="$personal_root/cache/qr-models-wechat" \
        -DPython3_EXECUTABLE="$(command -v python3)")
}

personal_dmg() {
    /usr/bin/hdiutil create -volname 'Snow Shot' -srcfolder "$personal_release/dmg-root" \
        -format UDZO "$personal_release/$personal_dmg_name"
    (cd "$personal_release"
        shasum -a 256 "$personal_dmg_name" > "$personal_dmg_name.sha256")
}

case "$personal_mode" in
    status)
        printf 'Personal root: %s\nArtifacts: %s\nTest data: %s\n' \
            "$personal_root" "$personal_root/artifacts" "$personal_root/user-data"
        du -sh "$personal_root"
        ;;
    bootstrap) personal_bootstrap ;;
    dependencies) personal_dependencies ;;
    qt-dependencies) personal_qt_dependencies ;;
    qt) personal_qt ;;
    configure) personal_configure "$personal_root/build" OFF OFF ;;
    configure-tests) personal_configure "$personal_root/build" ON OFF ;;
    icon)
        cmake --build "$personal_root/build" --target snow_shot/macos/snow-shot.icns --parallel 1
        ;;
    build)
        personal_configure "$personal_root/build" OFF OFF
        cmake --build "$personal_root/build" --target snow_shot --parallel "$personal_jobs"
        ;;
    build-target)
        [[ $# -gt 0 ]] || { echo 'Specify focused CMake targets' >&2; exit 2; }
        cmake --build "$personal_root/build" --target "$@" --parallel "$personal_jobs"
        ;;
    translations)
        personal_configure "$personal_root/build" OFF OFF
        cmake --build "$personal_root/build" --target snow_shot_update_translations --parallel "$personal_jobs"
        ;;
    performance) personal_configure "$personal_root/performance" ON ON ;;
    native-tests)
        cmake -S "$personal_repo/test-support/macos14-personal" -B "$personal_root/native-tests" -G Ninja \
            -DCMAKE_BUILD_TYPE=Release -DCMAKE_OSX_ARCHITECTURES=x86_64 -DCMAKE_OSX_DEPLOYMENT_TARGET=14.4 \
            -DQt6_DIR="$personal_root/qt/lib/cmake/Qt6"
        cmake --build "$personal_root/native-tests" --parallel "$personal_jobs"
        ctest --test-dir "$personal_root/native-tests" --output-on-failure \
            -R '^snow-shot-macos(14-personal|\-upstream-update)-tests$'
        ;;
    app-tests|storage-tests)
        personal_configure "$personal_root/build" ON OFF
        cmake --build "$personal_root/build" --target snow-shot-macos14-personal-storage-tests \
            snow-shot-image-codec-backend-smoke-tests snow-shot-configuration-archive-tests \
            snow-shot-login-item-tests snow-shot-about-page-tests \
            --parallel "$personal_jobs"
        ctest --test-dir "$personal_root/build" --output-on-failure \
            -R '^snow-shot-(macos14-personal-storage|image-codec-backend-smoke|configuration-archive|login-item|about-page)-tests$'
        personal_configure "$personal_root/build" OFF OFF
        ;;
    test)
        [[ $# -gt 0 ]] || { echo 'Specify a focused Rust test filter' >&2; exit 2; }
        cargo test --manifest-path "$personal_repo/snow-crates/Cargo.toml" -p snow-macos --lib "$@"
        ;;
    package)
        personal_app="$personal_release/Snow Shot.app"
        [[ ! -e "$personal_app" ]] || { echo 'Move the existing app aside before repackaging' >&2; exit 2; }
        [[ ! -e "$personal_release/dmg-root" ]] || { echo 'Move existing DMG staging aside before repackaging' >&2; exit 2; }
        cmake --install "$personal_root/build" --component SnowShot --prefix "$personal_release/staging"
        mv "$personal_release/staging/snow_shot.app" "$personal_app"
        mkdir -p "$personal_release/dmg-root"
        /usr/bin/ditto "$personal_app" "$personal_release/dmg-root/Snow Shot.app"
        ln -s /Applications "$personal_release/dmg-root/Applications"
        personal_dmg
        ;;
    dmg) personal_dmg ;;
    sources)
        python3 "$personal_repo/scripts/collect-maintained-sources.py" --prepare \
            --archive "$personal_release/snow-shot-$personal_version-third-party-sources.tar.gz"
        ;;
    run)
        exec "$personal_release/Snow Shot.app/Contents/MacOS/snow_shot" "$@"
        ;;
    probe)
        export QT_QPA_PLATFORM=cocoa
        exec "$personal_root/build/snow_shot/snow_shot.app/Contents/MacOS/snow_shot" --startup-probe
        ;;
    measure)
        [[ $# -ge 2 ]] || { echo 'Usage: macos14-personal.sh measure SECONDS PID [PID ...]' >&2; exit 2; }
        xcrun clang++ -std=c++17 -O2 -mmacosx-version-min=14.4 \
            "$personal_repo/scripts/macos14-personal-memory.cpp" -o "$personal_root/host/bin/memory-sampler"
        exec "$personal_root/host/bin/memory-sampler" "$@"
        ;;
    all)
        personal_bootstrap
        personal_qt_dependencies
        personal_qt
        personal_dependencies
        personal_configure "$personal_root/build" OFF OFF
        cmake --build "$personal_root/build" --target snow_shot --parallel "$personal_jobs"
        ;;
    *) echo 'Modes: status bootstrap dependencies qt-dependencies qt configure configure-tests build build-target translations performance native-tests app-tests probe test package sources run measure all clean [--all]' >&2; exit 2 ;;
esac
